require 'json';require 'digest'
o=File.expand_path(__dir__);p=ARGV.fetch(0,o+'/scalar-controls.json');r=JSON.parse(File.read(p));sha=->(p){Digest::SHA256.file(p).hexdigest}
raise 'Not completed' unless %w[passed failed].include?(r['status'])
r.fetch('identities').each{|p,h|raise 'Identity drift' unless sha.call(p)==h}
expected=%w[scalar-first collection-first scalar-only].product([3,8,64,2048],%w[once fresh],[1,2,16,32],%w[vm jit])
key=->(x){x.values_at('shape','width','snapshot','calls','mode')}
raise 'Exact allocation matrix' unless r.fetch('rows').map{|x|key.call(x['baseline'])}.sort==expected.sort
references={};sources={}
r.fetch('references').each do |path,h|
 raise 'Reference drift' unless sha.call(path)==h
 b=JSON.parse(File.read(path));raise 'Bad baseline' unless b['status']=='characterized'
 b['identities'].merge(b['sources']).each{|p,h|raise 'Baseline drift' unless sha.call(p)==h}
 sources.merge!(b['sources']);b['rows'].each{|x|references[key.call(x)]=x}
end
semantics=[]
r['rows'].each do |x|
 old=x['baseline'];raise 'Baseline substitution' unless references[key.call(old)]==old
 argv=[o+'/task-allocation-probe',old['mode'],old['path']]
 raise 'Invocation' unless x['argv']==argv&&x['exit']==0&&x['stdout']=="SCALAR FIRST PASS\n"
 raise 'Raw counts' unless x['stderr'].scan(/requests=(\d+) requested_bytes=(\d+)/)==[[x['requests'].to_s,x['bytes'].to_s]]
 if old['mode']=='vm'
  %w[vm interpreter jit].each{|mode|semantics<<[o+'/candidate-kujo','run',old['path'],'--untrusted','--scheduler-no-timeout']+(mode=='vm' ? [] : ['--'+mode])}
 end
end
raise 'Semantic matrix' unless r['semantics'].map{|x|x['argv']}.sort==semantics.sort&&semantics.uniq.size==288
raise 'Semantic result' unless r['semantics'].all?{|x|x['exit']==0&&x['stdout']=="SCALAR FIRST PASS\n"}
contracts=%w[vm interpreter jit].map{|mode|[o+'/candidate-kujo','run',o+'/scalar-contract/main.kujo','--untrusted']+(mode=='vm' ? [] : ['--'+mode])}
raise 'Contracts' unless r.fetch('contracts').map{|x|x['argv']}.sort==contracts.sort&&r['contracts'].all?{|x|x['exit']==0&&x['stdout']=="SCALAR BATCH CONTRACT PASS\n"}
regressions=r['rows'].select{|x|%w[requests bytes].any?{|m|x[m]>x['baseline'][m]}}
raise 'Regression list' unless regressions==r['regressions']
slopes=r['rows'].group_by{|x|x['baseline'].values_at('shape','width','snapshot','mode')}.map do |group,rows|
 a,b=rows.sort_by{|x|x['baseline']['calls']}.last(2)
 {'group'=>group,'bytes'=>(b['bytes']-a['bytes'])/16.0,'requests'=>(b['requests']-a['requests'])/16.0,'baseline_bytes'=>(b['baseline']['bytes']-a['baseline']['bytes'])/16.0,'baseline_requests'=>(b['baseline']['requests']-a['baseline']['requests'])/16.0}
end
raise 'Slope data' unless slopes==r['slopes']&&slopes.size==48
bad_slopes=slopes.select{|x|x['bytes']>x['baseline_bytes']||x['requests']>x['baseline_requests']}
raise 'Slope regressions' unless bad_slopes==r['slope_regressions']
passed=regressions.empty?&&bad_slopes.empty?
raise 'Incorrect status' unless (r['status']=='passed')==passed
receipt={status:passed ? 'passed' : 'verified-regressions',allocation_pairs:192,semantic_cases:288,contracts:3,total_regressions:regressions.size,slope_regressions:bad_slopes.size,report_sha256:sha.call(p),verifier_sha256:sha.call(__FILE__)}
File.write(o+'/scalar-controls-verified.json',JSON.pretty_generate(receipt)+"\n")
puts JSON.generate(receipt)

